var GS = GameState.state
var keep = ["U_CUSTODIAN_GUARD_B", "U_BLADE_CHAMPION_A", "U_BOYZ_E"]
for uid in GS["units"].keys():
	if uid in keep:
		continue
	var i = 0
	for m in GS["units"][uid]["models"]:
		m["position"] = {"x": 25000.0 + float(i) * 60.0, "y": 25000.0}
		i += 1
GS["meta"]["active_player"] = 1
return "parked"

var GS = GameState.state
var guard = GS["units"]["U_CUSTODIAN_GUARD_B"]["models"]
var gx = 1200.0
for i in range(guard.size()):
	guard[i]["alive"] = true
	guard[i]["position"] = {"x": gx + float(i) * 66.0, "y": 728.7}
GS["units"]["U_BLADE_CHAMPION_A"]["models"][0]["alive"] = true
GS["units"]["U_BLADE_CHAMPION_A"]["models"][0]["position"] = {"x": gx + 66.0, "y": 791.7}
# One live Boy facing each Guard model; every other Boy stays parked. The
# fixture already has casualties in this mob, so index 0 is not necessarily
# alive — and a dead model is skipped by every range check.
var ms = GS["units"]["U_BOYZ_E"]["models"]
for i in range(ms.size()):
	ms[i]["position"] = {"x": 25000.0 + float(i) * 60.0, "y": 25000.0}
var placed = []
for i in range(ms.size()):
	if placed.size() >= guard.size():
		break
	if ms[i].get("alive", true):
		ms[i]["position"] = {"x": gx + float(placed.size()) * 66.0, "y": 600.0}
		placed.append("U_BOYZ_E#%d" % i)
return " ".join(placed)

var GS = GameState.state
var boyz = []
for m in GS["units"]["U_BOYZ_E"]["models"]:
	if m.get("alive", true) and float(m["position"]["y"]) < 10000.0:
		boyz.append(m)
var worst_guard = 0.0
for g in GS["units"]["U_CUSTODIAN_GUARD_B"]["models"]:
	var best = 9999.0
	for b in boyz:
		best = min(best, Measurement.model_to_model_distance_inches(g, b))
	worst_guard = max(worst_guard, best)
var champ = GS["units"]["U_BLADE_CHAMPION_A"]["models"][0]
var champ_d = 9999.0
for b in boyz:
	champ_d = min(champ_d, Measurement.model_to_model_distance_inches(champ, b))
return "boyz=%d guard=%.2f champ=%.2f er=%.1f" % [boyz.size(), worst_guard, champ_d, GameConstants.engagement_range_inches()]

var GS = GameState.state
var g = RulesEngine.get_eligible_melee_model_indices(GS["units"]["U_CUSTODIAN_GUARD_B"], GS)
var c = RulesEngine.get_eligible_melee_model_indices(GS["units"]["U_BLADE_CHAMPION_A"], GS)
return "guard=%d champ=%d" % [g.size(), c.size()]

var d = Engine.get_main_loop().root.get_node_or_null("AttackAssignmentDialog")
var out = []
for g in d._groups:
	out.append("%s x%d" % [str(g.get("owner", "")), int(g.get("models", []).size())])
out.sort()
return " | ".join(out)

var d = Engine.get_main_loop().root.get_node_or_null("AttackAssignmentDialog")
var n = d.get_node_or_null("Content/SittingOutNote")
var t = str(n.text)
return "%s|%s|%s" % [str("Blade Champion" in t), str("3.4" in t), str("2\"" in t)]

var GS = GameState.state
var ms = GS["units"]["U_BOYZ_E"]["models"]
for i in range(ms.size()):
	if ms[i].get("alive", true) and float(ms[i]["position"]["y"]) > 10000.0:
		ms[i]["position"] = {"x": 1266.0, "y": 860.0}
		return "U_BOYZ_E#%d moved behind the Champion" % i
return "no spare Boy"

var GS = GameState.state
var g = RulesEngine.get_eligible_melee_model_indices(GS["units"]["U_CUSTODIAN_GUARD_B"], GS)
var c = RulesEngine.get_eligible_melee_model_indices(GS["units"]["U_BLADE_CHAMPION_A"], GS)
return "guard=%d champ=%d" % [g.size(), c.size()]

var d = Engine.get_main_loop().root.get_node_or_null("AttackAssignmentDialog")
var out = []
for g in d._groups:
	out.append("%s x%d" % [str(g.get("owner", "")), int(g.get("models", []).size())])
out.sort()
return " | ".join(out)
